INSERT INTO public.healthcare_providers (name, name_en, provider_type, specialty, specialty_en, description, description_en, address, address_en, city, country_code, phone, website, is_featured, is_active) SELECT 'Klinik für Frauenheilkunde und Geburtshilfe – Universitätsklinikum Frankfurt', 'Department of Obstetrics and Gynecology – University Hospital Frankfurt', 'hospital', 'Frauenheilkunde, Geburtshilfe, Brustzentrum, gynäkologische Onkologie, Reproduktionsmedizin', 'Obstetrics & Gynecology, Breast Center, Gynecologic Oncology, Reproductive Medicine', 'Die Universitäts-Frauenklinik Frankfurt bietet das komplette Spektrum der Frauenheilkunde und Geburtshilfe, von Kinderwunschbehandlung bis zur gynäkologischen Krebstherapie.', 'The University Women''s Clinic in Frankfurt provides the full spectrum of obstetrics and gynecology, from fertility treatment to gynecological cancer care.', 'Theodor-Stern-Kai 7, Haus 15, 60590 Frankfurt am Main', 'Theodor-Stern-Kai 7, Haus 15, 60590 Frankfurt am Main', 'Frankfurt am Main', 'DE', '+49 69 6301-5115', 'https://www.unimedizin-ffm.de/einrichtungen/kliniken/klinik-fuer-frauenheilkunde-und-geburtshilfe', true, true WHERE NOT EXISTS (SELECT 1 FROM public.healthcare_providers WHERE name_en = 'Department of Obstetrics and Gynecology – University Hospital Frankfurt' AND country_code = 'DE');
INSERT INTO public.healthcare_providers (name, name_en, provider_type, specialty, specialty_en, description, description_en, address, address_en, city, country_code, phone, website, is_featured, is_active) SELECT 'Klinik für Frauenheilkunde und Geburtshilfe – Universitätsklinikum Essen', 'Department of Obstetrics and Gynecology – University Hospital Essen', 'hospital', 'Frauenheilkunde, Geburtshilfe, Perinatalzentrum Level 1', 'Obstetrics & Gynecology, Level 1 Perinatal Center', 'Die Klinik für Frauenheilkunde und Geburtshilfe des Universitätsklinikums Essen deckt das gesamte Spektrum von Gynäkologie und Geburtshilfe ab und ist rund um die Uhr geöffnet.', 'The Department of Obstetrics and Gynecology at University Hospital Essen covers the full spectrum of gynecology and obstetrics and is open 24 hours a day.', 'Hufelandstraße 55, 45147 Essen', 'Hufelandstraße 55, 45147 Essen', 'Essen', 'DE', '+49 201 723-2441', 'https://www.uk-essen.de/klinik/frauenheilkunde-geburtshilfe/', true, true WHERE NOT EXISTS (SELECT 1 FROM public.healthcare_providers WHERE name_en = 'Department of Obstetrics and Gynecology – University Hospital Essen' AND country_code = 'DE');
INSERT INTO public.healthcare_providers (name, name_en, provider_type, specialty, specialty_en, description, description_en, address, address_en, city, country_code, phone, website, is_featured, is_active) SELECT 'Klinik und Poliklinik für Frauenheilkunde und Geburtshilfe – Universitätsklinikum Dresden', 'Department of Obstetrics and Gynecology – Dresden University Hospital', 'hospital', 'Frauenheilkunde, Geburtshilfe, gynäkologisches Krebszentrum, Kinderwunschzentrum', 'Obstetrics & Gynecology, Gynecologic Cancer Center, Fertility Center', 'Die Klinik für Frauenheilkunde und Geburtshilfe am Uniklinikum Dresden bietet ein umfassendes Leistungsspektrum in operativer und konservativer Frauenheilkunde, Fortpflanzungsmedizin und Geburtshilfe.', 'The Department of Obstetrics and Gynecology at Dresden University Hospital offers comprehensive services in surgical and conservative gynecology, reproductive medicine, and obstetrics.', 'Fetscherstraße 74, 01307 Dresden', 'Fetscherstraße 74, 01307 Dresden', 'Dresden', 'DE', '+49 351 458-2183', 'https://www.uniklinikum-dresden.de/de/das-klinikum/kliniken-polikliniken-institute/gyn', true, true WHERE NOT EXISTS (SELECT 1 FROM public.healthcare_providers WHERE name_en = 'Department of Obstetrics and Gynecology – Dresden University Hospital' AND country_code = 'DE');
INSERT INTO public.healthcare_providers (name, name_en, provider_type, specialty, specialty_en, description, description_en, address, address_en, city, country_code, phone, website, is_featured, is_active) SELECT 'Klinik und Poliklinik für Frauenheilkunde – Universitätsklinikum Leipzig', 'Department of Gynecology and Obstetrics – Leipzig University Hospital', 'hospital', 'Frauenheilkunde, gynäkologische Onkologie', 'Gynecology, Gynecologic Oncology', 'Die Klinik und Poliklinik für Frauenheilkunde des Universitätsklinikums Leipzig berät und behandelt umfassend bei allen Erkrankungen der weiblichen Genitale und der Brust.', 'The Department of Gynecology at Leipzig University Hospital provides comprehensive counseling and treatment for all diseases of the female genital organs and breast.', 'Liebigstraße 20a, Haus 6, 04103 Leipzig', 'Liebigstraße 20a, Haus 6, 04103 Leipzig', 'Leipzig', 'DE', '+49 341 97-23400', 'https://www.uniklinikum-leipzig.de/einrichtungen/frauenheilkunde', true, true WHERE NOT EXISTS (SELECT 1 FROM public.healthcare_providers WHERE name_en = 'Department of Gynecology and Obstetrics – Leipzig University Hospital' AND country_code = 'DE');
INSERT INTO public.healthcare_providers (name, name_en, provider_type, specialty, specialty_en, description, description_en, address, address_en, city, country_code, phone, website, is_featured, is_active) SELECT 'Klinik für Frauenheilkunde und Geburtshilfe – Universitätsklinikum Düsseldorf', 'Department of Obstetrics and Gynecology – University Hospital Düsseldorf', 'hospital', 'Frauenheilkunde, Geburtshilfe, Brustzentrum, gynäkologisches Krebszentrum', 'Obstetrics & Gynecology, Breast Center, Gynecologic Cancer Center', 'Die Klinik für Frauenheilkunde und Geburtshilfe am Universitätsklinikum Düsseldorf bietet das komplette Spektrum der Frauenheilkunde inklusive Brustzentrum, Geburtshilfe und Kinderwunschbehandlung.', 'The Department of Obstetrics and Gynecology at University Hospital Düsseldorf offers the full range of women''s health services, including a breast center, obstetrics, and fertility treatment.', 'Moorenstr. 5, 40225 Düsseldorf', 'Moorenstr. 5, 40225 Düsseldorf', 'Düsseldorf', 'DE', '+49 211 81-17501', 'https://www.uniklinik-duesseldorf.de/patienten-besucher/klinikeninstitutezentren/klinik-fuer-frauenheilkunde-und-geburtshilfe', true, true WHERE NOT EXISTS (SELECT 1 FROM public.healthcare_providers WHERE name_en = 'Department of Obstetrics and Gynecology – University Hospital Düsseldorf' AND country_code = 'DE');
INSERT INTO public.healthcare_providers (name, name_en, provider_type, specialty, specialty_en, description, description_en, address, address_en, city, country_code, phone, website, is_featured, is_active) SELECT 'Frauenklinik am Klinikum Stuttgart – Olgahospital', 'Women''s Clinic at Klinikum Stuttgart – Olgahospital', 'hospital', 'Geburtshilfe, Perinatalzentrum Level 1, gynäkologische Onkologie, Beckenbodenzentrum', 'Obstetrics, Level 1 Perinatal Center, Gynecologic Oncology, Pelvic Floor Center', 'Die Frauenklinik am Olgahospital des Klinikums Stuttgart zählt mit rund 3.500 Geburten pro Jahr zu den zehn größten Geburtskliniken Deutschlands.', 'The Women''s Clinic at Olgahospital, part of Klinikum Stuttgart, is among the ten largest maternity hospitals in Germany with around 3,500 births per year.', 'Kriegsbergstraße 62, 70174 Stuttgart', 'Kriegsbergstraße 62, 70174 Stuttgart', 'Stuttgart', 'DE', '+49 711 278-63101', 'https://www.klinikum-stuttgart.de/medizin-pflege/frauenklinik-schwerpunkt-geburtshilfe', true, true WHERE NOT EXISTS (SELECT 1 FROM public.healthcare_providers WHERE name_en = 'Women''s Clinic at Klinikum Stuttgart – Olgahospital' AND country_code = 'DE');
INSERT INTO public.healthcare_providers (name, name_en, provider_type, specialty, specialty_en, description, description_en, address, address_en, city, country_code, phone, website, is_featured, is_active) SELECT 'Zentrum für Geburtshilfe und Frauenheilkunde – Universitätsklinikum Bonn', 'Center for Obstetrics and Gynecology – University Hospital Bonn', 'hospital', 'Geburtshilfe, Frauenheilkunde, gynäkologische Onkologie, Reproduktionsmedizin, Senologie', 'Obstetrics, Gynecology, Gynecologic Oncology, Reproductive Medicine, Breast Care', 'Das Zentrum für Geburtshilfe und Frauenheilkunde am Universitätsklinikum Bonn vereint Geburtshilfe, Gynäkologie, Senologie und Reproduktionsmedizin unter einem Dach.', 'The Center for Obstetrics and Gynecology at University Hospital Bonn combines obstetrics, gynecology, breast care, and reproductive medicine under one roof.', 'Venusberg-Campus 1, 53127 Bonn', 'Venusberg-Campus 1, 53127 Bonn', 'Bonn', 'DE', '+49 228 287-15450', 'https://www.ukbonn.de/frauenklinik-zentrum/', true, true WHERE NOT EXISTS (SELECT 1 FROM public.healthcare_providers WHERE name_en = 'Center for Obstetrics and Gynecology – University Hospital Bonn' AND country_code = 'DE');
INSERT INTO public.healthcare_providers (name, name_en, provider_type, specialty, specialty_en, description, description_en, address, address_en, city, country_code, phone, website, is_featured, is_active) SELECT 'Klinik für Frauenheilkunde und Geburtshilfe – Universitätsklinikum Münster', 'Department of Obstetrics and Gynecology – University Hospital Münster', 'hospital', 'Allgemeine Gynäkologie, gynäkologische Onkologie, Geburtshilfe und Pränatalmedizin, Senologie, Reproduktionsmedizin', 'General Gynecology, Gynecologic Oncology, Obstetrics & Prenatal Medicine, Breast Care, Reproductive Medicine', 'Die Klinik für Frauenheilkunde und Geburtshilfe am UKM Münster bietet eine Rundumversorgung von Frauen in allen Lebensphasen, u.a. mit Schwerpunkt Endometriose und gynäkologische Krebserkrankungen.', 'The Department of Obstetrics and Gynecology at UKM Münster offers comprehensive care for women at all life stages, with specialties including endometriosis and gynecological cancers.', 'Albert-Schweitzer-Campus 1, Gebäude A1, 48149 Münster', 'Albert-Schweitzer-Campus 1, Gebäude A1, 48149 Münster', 'Münster', 'DE', '+49 251 83-48015', 'https://www.ukm.de/kliniken/frauenheilkunde-geburtshilfe', true, true WHERE NOT EXISTS (SELECT 1 FROM public.healthcare_providers WHERE name_en = 'Department of Obstetrics and Gynecology – University Hospital Münster' AND country_code = 'DE');
INSERT INTO public.healthcare_providers (name, name_en, provider_type, specialty, specialty_en, description, description_en, address, address_en, city, country_code, phone, website, is_featured, is_active) SELECT 'Klinik und Poliklinik für Geburtshilfe und Frauengesundheit – Universitätsmedizin Mainz', 'Department of Obstetrics and Women''s Health – University Medical Center Mainz', 'hospital', 'Geburtshilfe, Frauengesundheit, Brustzentrum, gynäkologisches Krebszentrum, Kinderwunschzentrum', 'Obstetrics, Women''s Health, Breast Center, Gynecologic Cancer Center, Fertility Center', 'Die Klinik und Poliklinik für Geburtshilfe und Frauengesundheit der Universitätsmedizin Mainz ist das einzige Perinatalzentrum Level I in Mainz und bietet umfassende Frauenheilkunde.', 'The Department of Obstetrics and Women''s Health at Mainz University Medical Center is the only Level I perinatal center in Mainz and offers comprehensive gynecological care.', 'Gebäude 102, Langenbeckstraße 1, 55131 Mainz', 'Gebäude 102, Langenbeckstraße 1, 55131 Mainz', 'Mainz', 'DE', '+49 6131 17-2456', 'https://www.unimedizin-mainz.de/frauenklinik/', true, true WHERE NOT EXISTS (SELECT 1 FROM public.healthcare_providers WHERE name_en = 'Department of Obstetrics and Women''s Health – University Medical Center Mainz' AND country_code = 'DE');
